  GENERATOR_HALT,
  runGeneratorMiddleware
} from '@migaia/middleware-pipeline';

runGeneratorMiddleware(
  [
    function* (value: number) {
      yield value + 1;
      yield value + 2; // 最终采用这一次
      return GENERATOR_CONTINUE;
    },
    function* (value: number) {
      if (value > 10) return GENERATOR_HALT; // 终止整条链
      return value * 2;
    }
  ],
  3,
  (value) => console.log(value) // 10
);

const GENERATOR_UNDEFINED: unique symbol;
const GENERATOR_HALT: unique symbol;
const GENERATOR_CONTINUE: unique symbol;

type IGeneratorMiddlewareSignals = {
  readonly undefined: symbol;
  readonly halt: symbol;
  readonly continue: symbol;
};
const MiddlewarePipelineGeneratorSignals: IGeneratorMiddlewareSignals;

import {
  GENERATOR_CONTINUE,
  GENERATOR_HALT,
  GENERATOR_UNDEFINED,
  MiddlewarePipelineGeneratorSignals
} from '@migaia/middleware-pipeline';

function* stage(value: number) {
  yield value;
  return GENERATOR_CONTINUE; // 或 GENERATOR_HALT / GENERATOR_UNDEFINED
}

function runAsyncGeneratorMiddleware<TValue>(
  stages: readonly IAsyncGeneratorMiddlewareStage<TValue>[],
  value: TValue,
  done: (value: TValue) => void | Promise<void>,
  signals?: IGeneratorMiddlewareSignals,
  control?: IMiddlewarePipelineControlOptions
): Promise<void>;

function adaptGeneratorStageToAsyncGenerator<TValue>(
  stage: IGeneratorMiddlewareStage<TValue>
): IAsyncGeneratorMiddlewareStage<TValue>;

function adaptSyncStageToAsyncGenerator<TValue>(
  stage: ISyncMiddlewareStage<TValue>,
  onViolation: IMiddlewarePipelineViolationHandler
): IAsyncGeneratorMiddlewareStage<TValue>;

import {
  GENERATOR_CONTINUE,
  runAsyncGeneratorMiddleware,
  type IAsyncGeneratorMiddlewareStage
} from '@migaia/middleware-pipeline';

const fetchStage: IAsyncGeneratorMiddlewareStage<string> = async function* (url, context) {
  yield url; // 中间 yield 仅用于观测/调试，不会提前送到下一 stage
  const response = await fetch(url, { signal: context?.signal as AbortSignal | undefined });
  return await response.text();
};

const controller = new AbortController();
setTimeout(() => controller.abort(new Error('超时')), 3000);

try {
  await runAsyncGeneratorMiddleware(
    [fetchStage],
    'https://example.com/data',
    (text) => console.log('done:', text),
    undefined,
    { signal: controller.signal }
  );
} catch (error) {
  // 3 秒内 controller.abort() 触发：runner 在下一个协作检查点抛出 '超时'（reason 已是 Error，原样抛出）
  // fetch 本身也收到同一个 signal，会独立中止网络请求
  console.error(error);
}

type IAsyncMiddlewareStage<TValue> = (
  value: TValue,
  next: (value: TValue) => Promise<void>, context?: IMiddlewarePipelineContext
) => void | Promise<void>;

