type ISyncMiddlewareStage<TValue> = (value: TValue, next: (value: TValue) => void, context?: IMiddlewarePipelineContext) => void;

function runSyncMiddleware<TValue>(
  stages: readonly ISyncMiddlewareStage<TValue>[],
  value: TValue,
  done: (value: TValue, context?: IMiddlewarePipelineContext) => void,
  onViolation: IMiddlewarePipelineViolationHandler,
  control?: IMiddlewarePipelineControlOptions
): void;

runSyncMiddleware(
  [(v: string, next) => next(v.trim()), (v: string, next) => next(v.toUpperCase())],
  ' hi ',
  (v) => console.log(v), // 'HI'
  () => undefined
);

import {
  runSyncMiddleware,
  runAsyncMiddleware,
  runGeneratorMiddleware,
  runAsyncGeneratorMiddleware
} from '@migaia/middleware-pipeline';

runSyncMiddleware(
  [
    (value: string, next) => next(value.trim()),
    (value: string, next) => {
      if (value.length === 0) return; // 不调用 next：短路，done 不执行
      next(value.toUpperCase());
    }
  ],
  ' migaia ',
  (value) => console.log(value), // 'MIGAIA'
  (violation) => console.warn(violation) // 'late' | 'duplicate'
);

const controller = new AbortController();
runSyncMiddleware([stage], value, done, onViolation, { signal: controller.signal });
controller.abort('user cancelled');

import { MiddlewarePipelineViolation, runSyncMiddleware } from '@migaia/middleware-pipeline';

const violations: string[] = [];

runSyncMiddleware(
  [
    (value: string, next) => next(value.trim()),
    (value: string, next) => {
      if (value.length === 0) return; // 空字符串直接短路
      next(value.toUpperCase());
      next('ignored'); // 触发 duplicate，只有第一次生效
    }
  ],
  '  hi  ',
  (value) => console.log('done:', value), // 'done: HI'
  (violation) => violations.push(violation) // ['duplicate']
);

